contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes32 identifier, uint256 time, bytes memory ancillaryData, bytes32 assertionId, address disputeCaller) public payable {
        // getAssertionPolicy returns the all-false policy
        C.AssertionPolicy memory policy = c.getAssertionPolicy(assertionId);
        assert(!policy.blockAssertion && !policy.arbitrateViaEscalationManager && !policy.discardOracle && !policy.validateDisputers);

        // isDisputeAllowed always returns true
        assert(c.isDisputeAllowed(assertionId, disputeCaller));

        // getPrice is view and returns without reverting (returns some value)
        int256 price = c.getPrice(identifier, time, ancillaryData);
        assert(price == price);

        // requestPrice from a non-asserter caller (this test) must revert
        bool reverted;
        try c.requestPrice(identifier, time, ancillaryData) { reverted = false; }
        catch { reverted = true; }
        assert(reverted);
    }
    receive() external payable {}
}

