contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes32 id, uint256 t, bytes memory anc) public {
        // Rule 1: getPrice always returns 0 for any input.
        int256 p = c.getPrice(id, t, anc);
        // Rule 2: disputes are always allowed.
        bool allowed = c.isDisputeAllowed(id, address(this));
        // Rule 3: the default assertion policy disables all special behaviors.
        C.AssertionPolicy memory pol = c.getAssertionPolicy(id);
        // Rule 4: requestPrice must revert when called by a non-asserter caller
        // (the test contract is not the optimistic asserter passed to the constructor).
        bool reverted;
        try c.requestPrice(id, t, anc) { reverted = false; } catch { reverted = true; }
        assert(
            p == 0 &&
            allowed == true &&
            pol.blockAssertion == false &&
            pol.arbitrateViaEscalationManager == false &&
            pol.discardOracle == false &&
            pol.validateDisputers == false &&
            reverted == true
        );
    }
}

